<?php declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__,2).'/vendor/autoload.php';require dirname(__DIR__,2).'/app/autoload.php';
use FMonitor2\InstallationProcess\{CanonicalMigrationApplication,ProductionPilotMigrationCatalogue};
$h=getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1';$port=(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306);$u=getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root';$pw=getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local';$a=new mysqli($h,$u,$pw,'',$port);$n='t_otiz_v2_upgrade_'.bin2hex(random_bytes(4));$db=null;
try{$a->query("CREATE DATABASE `{$n}` DEFAULT CHARSET=utf8mb4");$db=new mysqli($h,$u,$pw,$n,$port);$p='up_';$all=ProductionPilotMigrationCatalogue::migrations();$v36=array_filter($all,fn($v)=>$v<=36,ARRAY_FILTER_USE_KEY);$old=CanonicalMigrationApplication::run($db,$p,$v36);assertSameValue(36,$old['result']['schemaVersion']??null,'supported predecessor v36');
$db->query("INSERT INTO {$p}fm2_otiz_calculation_revisions(id,revision,status,report_date,actor_user_id,input_json,projection_json,created_at,updated_at)VALUES(91,1,'accepted','2026-09-01',1,'{}','{}','2026-09-01T00:00:00Z','2026-09-01T00:00:00Z')");$db->query("INSERT INTO {$p}fm2_otiz_entitlement_claims(calculation_id,object_id,source_kind,source_id,source_revision,entitlement_kind,recognition_date,gross_cents,active)VALUES(91,4512,'checklist','case-6101-checklist','legacy-r1','progress','2026-09-01',300000,1),(91,4512,'pto_act','completion-77','legacy-p1','pto','2026-09-01',100000,1)");$db->query("INSERT INTO {$p}fm2_otiz_admission_inputs(object_id,source_revision,decision,reason_code,observed_at,incident_id,operation_id,producer_user_id,evidence_json)VALUES(4512,'legacy-admission','blocked','LEGACY_BLOCK','2026-09-01T02:00:00Z','legacy-incident','00000000-0000-4000-8000-000000000091',1,'{}')");$db->query("CREATE TABLE {$p}fm2_otiz_entitlement_frontiers(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,right_key VARCHAR(255) NOT NULL,claimed_cents BIGINT NOT NULL,updated_at VARCHAR(40) NOT NULL,PRIMARY KEY(id),UNIQUE KEY right_key(right_key))ENGINE=InnoDB");$db->query("CREATE TABLE {$p}fm2_otiz_admission_events(generation BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,object_id BIGINT UNSIGNED NOT NULL,source_revision VARCHAR(120) NOT NULL,decision VARCHAR(24) NOT NULL,reason_code VARCHAR(80) NULL,observed_at VARCHAR(40) NOT NULL,incident_id VARCHAR(120) NULL,operation_id CHAR(36) NULL,producer_user_id BIGINT UNSIGNED NULL,evidence_json LONGTEXT NULL,PRIMARY KEY(generation),UNIQUE KEY operation_id(operation_id),KEY object_generation(object_id,generation))ENGINE=InnoDB");
$full=CanonicalMigrationApplication::run($db,$p,$all);assertSameValue(37,$full['result']['schemaVersion']??null,'additive corrected frontier');$frontiers=$db->query("SELECT right_key,claimed_cents FROM {$p}fm2_otiz_entitlement_frontiers ORDER BY right_key")->fetch_all(MYSQLI_ASSOC);assertSameValue([['right_key'=>'4512|checklist|case-6101-checklist|progress','claimed_cents'=>'300000'],['right_key'=>'4512|pto_act|completion-77|pto','claimed_cents'=>'100000']],$frontiers,'interrupted v37 retry reconciles every active v36 stable right exactly');$event=$db->query("SELECT object_id,source_revision,decision,reason_code,operation_id FROM {$p}fm2_otiz_admission_events")->fetch_row();assertSameValue(['4512','legacy-admission','blocked','LEGACY_BLOCK','00000000-0000-4000-8000-000000000091'],$event,'interrupted v37 retry reconciles admission history');$ddl=$db->query("SHOW CREATE TABLE {$p}fm2_otiz_admission_events")->fetch_array(MYSQLI_NUM)[1];assertSameValue(true,str_contains($ddl,'CHECK')&&str_contains($ddl,'reason_code'),'authoritative admission events enforce blocked reason');$again=CanonicalMigrationApplication::run($db,$p,$all);assertSameValue([$frontiers,37],[$db->query("SELECT right_key,claimed_cents FROM {$p}fm2_otiz_entitlement_frontiers ORDER BY right_key")->fetch_all(MYSQLI_ASSOC),$again['result']['schemaVersion']??null],'repeat migration does not double frontier cents');echo"settlement_v2_upgrade_001_test: OK\n";
foreach(['NULL',"'   '"]as$reason){try{$db->query("INSERT INTO {$p}fm2_otiz_admission_events(object_id,source_revision,decision,reason_code,observed_at)VALUES(9991,'constraint-test','blocked',{$reason},'2026-09-01T03:00:00Z')");throw new TestFailure('invalid blocked reason accepted');}catch(mysqli_sql_exception $error){assertSameValue(true,str_contains($error->getMessage(),'CONSTRAINT'),'blocked reason DB denial');}}$db->query("INSERT INTO {$p}fm2_otiz_admission_events(object_id,source_revision,decision,reason_code,observed_at)VALUES(9992,'constraint-allow','allow',NULL,'2026-09-01T03:01:00Z')");assertSameValue(1,(int)$db->query("SELECT COUNT(*) FROM {$p}fm2_otiz_admission_events WHERE object_id=9992")->fetch_column(),'allow permits NULL reason');
}finally{if($db instanceof mysqli)$db->close();$a->query("DROP DATABASE IF EXISTS `{$n}`");$a->close();}
